arguments.command:
mkdir -p /workspace/work && curl -s -m 10 http://127.0.0.1:8081/openapi.json -o /workspace/work/openapi_8081.json && curl -s -m 10 http://127.0.0.1:8082/openapi.json -o /workspace/work/openapi_8082.json && curl -s -m 10 http://127.0.0.1:8083/openapi.json -o /workspace/work/openapi_8083.json && python3 -I -c "
import json
for port in (8081,8082,8083):
    spec=json.load(open(f'/workspace/work/openapi_{port}.json'))
    print(f'===== {port}: {spec[\"info\"][\"title\"]} =====')
    for path,methods in spec['paths'].items():
        for m,info in methods.items():
            print(f'{m.upper():6} {path:45} {info.get(\"summary\",\"\")}')
"

