arguments.command:
python3 -I -c "
import json
for port in (8081,8082,8083):
    spec=json.load(open(f'/workspace/work/openapi_{port}.json'))
    print(f'===== {port} =====')
    for path,methods in spec['paths'].items():
        for m,info in methods.items():
            if 'requestBody' in info:
                print(m.upper(), path)
                print(json.dumps(info['requestBody'],indent=1)[:800])
    print('--- schemas ---')
    print(json.dumps(spec.get('components',{}).get('schemas',{}),indent=1)[:3000])
"

