41	  <img id="hmImg" src="/api/simulations/heatmap.png" style="max-width:100%;border-radius:8px;margin-top:10px;border:1px solid #334155">
42	</div>
43	<script>
44	let state = {racks:[], assignments:[]};
45	async function load(){
46	  const r = await fetch('/api/cluster'); state = await r.json();
47	  document.getElementById('quota').textContent = `Staging 仿真配额已用: ${state.simulations_used} / ${state.max_simulations} (剩余 ${state.simulations_remaining})`;
48	  renderRacks();
49	  const s = await fetch('/api/simulations/latest'); const sd = await s.json();
50	  document.getElementById('simOut').textContent = JSON.stringify(sd, null, 2);
51	  document.getElementById('hmImg').src = '/api/simulations/heatmap.png?t=' + Date.now();
52	}
53	function tcls(t){if(t.startsWith('PROD'))return 'PROD';if(t.startsWith('SHARED-AUTO-BU'))return 'AUTOBU';if(['T1','T3','T6'].includes(t))return 'HIGH';if(['T2','T4'].includes(t))return 'MED';return 'LOW';}
54	function renderRacks(){
55	  const box = document.getElementById('racks'); box.innerHTML = '';
56	  for(const rk of state.racks){
57	    const div = document.createElement('div');
58	    div.className = 'rack' + (rk.protected ? ' prot' : '');
59	    div.innerHTML = `<div><strong>${rk.rack}</strong> (${rk.spine})<br><span style="font-size:12px;color:#94a3b8">${rk.zone} | ${rk.has_rdma?'RDMA':'Std'} | ${rk.cap_kw}kW</span></div>`;
60	    for(const b of [3,2,1,0]){
61	      const bd = document.createElement('div'); bd.className = 'bay';
62	      bd.innerHTML = `<div style="font-size:11px;color:#94a3b8">Bay ${b}</div>`;
63	      const items = state.assignments.filter(a => a.rack===rk.rack && a.bay===b);
64	      for(const a of items){
65	        const ch = document.createElement('div'); ch.className = 'chip ' + tcls(a.team);
66	        const locked = rk.protected || a.team.startsWith('SHARED-AUTO-BU');
67	        const del = locked ? '<span style="color:#e9d5ff;font-size:10px">LOCKED</span>' : `<button onclick="rmAssign('${a.rack}',${a.bay},'${a.shift}')" style="background:none;border:none;color:#fca5a5;cursor:pointer">x</button>`;
68	        ch.innerHTML = `<span>${a.team} (${a.shift})${a.rdma?'+RDMA':''}${a.priority_iops?'+IOPS':''}</span>${del}`;
69	        bd.appendChild(ch);
70	      }
71	      div.appendChild(bd);
72	    }
73	    box.appendChild(div);
74	  }
75	}
76	function rmAssign(rack, bay, shift){
77	  state.assignments = state.assignments.filter(a => !(a.rack===rack && a.bay===bay && a.shift===shift));
78	  renderRacks();
79	}
80	function addAssign(){
81	  const rack=fRack.value, bay=+fBay.value, shift=fShift.value, team=fTeam.value, rdma=fRdma.checked, priority_iops=fIops.checked;
82	  state.assignments = state.assignments.filter(a => !(a.rack===rack && a.bay===bay && (shift==='24H'||a.shift==='24H'||a.shift===shift)));
83	  state.assignments.push({rack,bay,shift,team,rdma,priority_iops});
84	  renderRacks();
85	}
86	async function saveAll(){
87	  const r = await fetch('/api/allocations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({assignments:state.assignments})});
88	  const d = await r.json(); if(!r.ok) alert(d.detail||JSON.stringify(d)); else await load();
89	}
90	async function runSim(){
91	  const r = await fetch('/api/simulations/run',{method:'POST'});
92	  const d = await r.json(); if(!r.ok) alert(d.detail||JSON.stringify(d)); else await load();
93	}
94	load();
95	</script></body></html>

